// Generated by Joinery. Enforces the creation-only gate (Rule Zero).
// Runs `joinery hook` before every tool call and blocks on a non-zero exit.
import { spawnSync } from 'node:child_process'

export const JoineryGate = async () => ({
  'tool.execute.before': async (input, output) => {
    const payload = JSON.stringify({
      tool: input.tool,
      server: input.server ?? '',
      args: output?.args ?? {},
      directory: input.directory ?? process.cwd(),
    })
    const argv = ["uv", "run", "--frozen", "--quiet", "joinery", "hook", "--agent", "opencode"]
    const res = spawnSync(argv[0], argv.slice(1), { input: payload, encoding: 'utf8' })
    if (res.status !== 0) {
      throw new Error(res.stderr?.trim() || 'Blocked by Joinery policy')
    }
  },
})
